#include <vector>
#include <algorithm>

class Solution {
public:
    long long countBipartiteIntersectingPairs(
        std::vector<std::vector<int>>& intervals_a,
        std::vector<std::vector<int>>& intervals_b
    ) {
        long long n = intervals_a.size(), m = intervals_b.size();
        long long total = n * m;

        std::vector<int> b_starts, b_ends;
        for (auto const& iv : intervals_b) {
            b_starts.push_back(iv[0]);
            b_ends.push_back(iv[1]);
        }
        std::sort(b_starts.begin(), b_starts.end());
        std::sort(b_ends.begin(), b_ends.end());

        long long disjoint = 0;
        for (auto const& iv : intervals_a) {
            int sa = iv[0], ea = iv[1];
            int b_before_a = std::lower_bound(b_ends.begin(), b_ends.end(), sa) - b_ends.begin();
            int b_after_a = b_starts.end() - std::upper_bound(b_starts.begin(), b_starts.end(), ea);
            disjoint += b_before_a + b_after_a;
        }
        return total - disjoint;
    }
};

import java.util.*;

class Solution {
    public long countBipartiteIntersectingPairs(int[][] a, int[][] b) {
        long n = a.length, m = b.length;
        long total = n * m;

        int[] bStarts = new int[(int) m];
        int[] bEnds = new int[(int) m];
        for (int i = 0; i < m; i++) {
            bStarts[i] = b[i][0];
            bEnds[i] = b[i][1];
        }
        Arrays.sort(bStarts);
        Arrays.sort(bEnds);

        long disjoint = 0;
        for (int[] iv : a) {
            int sa = iv[0], ea = iv[1];
            int bBeforeA = bisectLeft(bEnds, sa);
            int bAfterA = (int) m - bisectRight(bStarts, ea);
            disjoint += bBeforeA + bAfterA;
        }
        return total - disjoint;
    }

    private int bisectLeft(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = l + (r - l) / 2;
            if (arr[mid] >= target) r = mid;
            else l = mid + 1;
        }
        return l;
    }

    private int bisectRight(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = l + (r - l) / 2;
            if (arr[mid] > target) r = mid;
            else l = mid + 1;
        }
        return l;
    }
}

