    const total = n * m;

    const bStarts = b.map(iv => iv[0]).sort((x, y) => x - y);
    const bEnds = b.map(iv => iv[1]).sort((x, y) => x - y);

    let disjoint = 0;
    for (const [sa, ea] of a) {
        let l = 0, r = m;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (bEnds[mid] >= sa) r = mid;
            else l = mid + 1;
        }
        const bBeforeA = l;

        l = 0; r = m;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (bStarts[mid] > ea) r = mid;
            else l = mid + 1;
        }
        const bAfterA = m - l;
        disjoint += bBeforeA + bAfterA;
    }
    return total - disjoint;
}
